command:
// ==========================================
// LUNAS WIRKUNG: TOTE ERWECKEN (BRONA)
//
// - Multi-Ziel-Unterstützung: Verwandelt ALLE im Target ausgewählten besiegten LEBENDIGEN Wesen, solange das Limit (QS × 2) reicht
// - nutzt DSK.Wesen.IstLebendig zum Ausschließen von Geistern, Untoten, etc.
// - Misserfolge zeigen strikt nur den reinen Namen ohne Zusatztexte
// - Verknüpfte Effekte: SOWOHL Diener ALS AUCH Caster (Kontrolleffekt) werden verborgen (disabled: true) angelegt
// - gespeicherte Ziele | GM-Button | gemeinsame Karte über GabenUI
// ==========================================

(async function () {
    const macroUuid = this?.uuid || game.macros.getName("Tote erwecken")?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++
    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.Wesen?.IstLebendig ||
        !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;
    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
        !DSK_FW?.Wesen?.IstLebendig ||
        !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++
    const gabenName = "Tote erwecken", vollerName = "Tote erwecken (Brona)", ahne = "Brona";
    const flagKey = "pendingToteErweckenBrona", endeKey = "toteErweckenBrona";
    const endeText = "Die dunkle Magie verblasst. Die Bindung zum untoten Diener ist gerissen, der Körper fällt leblos zu Boden und die maximalen AeP des Beschwörers sind wiederhergestellt.";

    DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

    // +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++
    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
    };

    const ladeActor = async uuid => {
        if (!uuid) return null;
        try {
            const doc = await fromUuid(uuid);
            return doc?.documentName === "Token" ? doc.actor : doc || null;
        } catch (error) {
            console.warn("Tote erwecken: Actor konnte nicht geladen werden.", { uuid, error });
            return null;
        }
    };

    const istGueltigesLebewesen = actor => {
        if (!actor) return false;
        return DSK_FW.Wesen.IstLebendig(actor, { zusaetzlichAusgeschlossen: ["elementar", "pflanze"] });
    };

    const istBesiegt = (actor, token = null) => {
        if (!actor) return false;
        if (token?.combatant?.defeated === true) return true;

        return (actor.effects || []).some(effekt => {
            if (effekt.disabled) return false;
            const name = String(effekt.name || effekt.label || "").trim().toLowerCase();
            if (name === "tot" || name === "besiegt" || name.includes("dead") || name.includes("besiegt")) return true;

            const statusIds = Array.from(effekt.statuses || []).map(s => String(s).toLowerCase());
            if (statusIds.some(s => ["dead", "defeated", "besiegt", "tot"].includes(s))) return true;

            const coreStatus = String(effekt.getFlag("core", "statusId") || "").toLowerCase();
            return ["dead", "defeated", "besiegt", "tot"].includes(coreStatus);
        });
    };

    const zaehleKontrollierteDiener = actor => {
        return (actor?.effects || []).filter(e => {
            const n = e.name || e.label || "";
            return n.includes(vollerName) && n.includes("Kontrolle");
        }).length;
    };

    const findeCasterEffekte = (actor, targetUuid) =>
        (actor?.effects || []).filter(e => {
            const n = e.name || e.label || "";
            return n.includes(vollerName) && (e.getFlag("dsk", "targetUuid") === targetUuid || n.includes(targetUuid));
        });

    const findeZielEffekte = actor =>
        (actor?.effects || []).filter(e => {
            const n = e.name || e.label || "";
            return n.includes(vollerName) && n.includes("Katzendiener");
        });

    const beschreibungFuer = (casterName, reichweite, dienerZahl, maxDiener) =>
        `Die düstere Magie von Brona fließt in die ausgewählten gefallenen Wesen. Die leblosen Augen öffnen sich erneut.` +
        `<br><br>Die Körper haben sich als <b>Untote Katzendiener</b> erhoben und warten gehorsam auf Befehle!` +
        `<br><br><b>Telepathische Kontrolle:</b>` +
        `<br>• Du kannst im Umkreis von <b>${reichweite} Schritt</b> durch die Augen der Diener blicken und ihnen telepathisch Befehle erteilen.` +
        `<br>• Ohne Befehl greifen sie lebende Katzen an.` +
        `<br><br>• <b>Kontrollierte Diener:</b> ${dienerZahl} / ${maxDiener} (Limit: QS × 2)` +
        `<br>• <b>Max. AeP Malus:</b> −${dienerZahl} (auf ${casterName} aktiv)` +
        `<br><br><b>Zielkategorie:</b> Tote Lebewesen (keine Geister/Untote)`;

    // +++ 4 - EFFEKTE ANWENDEN +++++++++++++++++++++++++++++++++++++
    const wendeEffekteAn = async ({ casterActor, zieleListe, qs }) => {
        if (!casterActor || !zieleListe?.length) return { ok: false, erfolge: [], misserfolge: [] };

        const casterName = DSK_FW.ResolveTokenName(casterActor) || casterActor.name;
        const maxDienerZahl = qs * 2;
        const erfolge = [];
        const misserfolge = [];

        for (const ziel of zieleListe) {
            const targetActor = await ladeActor(ziel.actorUuid);
            const targetName = ziel.name;

            if (!targetActor || !istGueltigesLebewesen(targetActor) || !istBesiegt(targetActor)) {
                misserfolge.push({ name: targetName });
                continue;
            }

            const aktuelleDiener = zaehleKontrollierteDiener(casterActor);
            if (aktuelleDiener >= maxDienerZahl) {
                misserfolge.push({ name: targetName });
                continue;
            }

            // 1. Status "Tot / Besiegt" vom Ziel entfernen
            const deadEffects = (targetActor.effects || []).filter(e => {
                const n = (e.name || e.label || "").toLowerCase();
                const statusIds = Array.from(e.statuses || []).map(s => String(s).toLowerCase());
                return n === "tot" || n.includes("dead") || statusIds.includes("dead") || statusIds.includes("defeated") || e.flags?.core?.statusId === "dead";
            });
            for (const eff of deadEffects) {
                await eff.delete();
            }

            const maxLeP = Number(targetActor.system?.stats?.LeP?.max) || 1;
            await targetActor.update({ "system.stats.LeP.value": maxLeP });

            // 2. Alt-Effekte sauber bereinigen
            const alteCaster = findeCasterEffekte(casterActor, ziel.actorUuid);
            if (alteCaster.length) {
                await casterActor.deleteEmbeddedDocuments("ActiveEffect", alteCaster.map(e => e.id));
            }

            const alteZiel = findeZielEffekte(targetActor);
            if (alteZiel.length) {
                await targetActor.deleteEmbeddedDocuments("ActiveEffect", alteZiel.map(e => e.id));
            }

            // 3. Kontroll-Effekt beim Caster via Framework Block 6 (jetzt ebenfalls verborgen mit disabled: true)
            const kontrolleName = `${vollerName} - Kontrolle: ${targetName}`;
            const casterEffekt = await DSK_FW.Effekt.Anwenden({
                name: kontrolleName,
                ahne,
                beschreibung: `Du kontrollierst den untoten Katzendiener <b>${targetName}</b>. Deine maximalen AeP sind um 1 gesenkt.`,
                gabeZiel: "",
                qs,
                skills: ["system.stats.AeP.gearmodifier"],
                key: "direkterSystemwert",
                formel: "-1",
                ziel: casterActor,
                disabled: true,
                showIcon: 1,
                flags: {
                    dsk: {
                        isToteErweckenCaster: true,
                        casterUuid: casterActor.uuid,
                        targetUuid: ziel.actorUuid,
                        qs,
                        wirkungsende: {
                            sfName: endeKey,
                            basisEffektName: vollerName,
                            beschreibungFuerEnde: endeText
                        }
                    }
                }
            });

            if (!casterEffekt) {
                misserfolge.push({ name: targetName });
                continue;
            }

            // 4. Diener-Effekt beim Ziel via Framework Block 6 (verborgen mit disabled: true)
            const zielEffektName = `${vollerName} - Katzendiener`;
            const zielEffekt = await DSK_FW.Effekt.Anwenden({
                name: zielEffektName,
                ahne,
                beschreibung: `Wurde von <b>${casterName}</b> als Untoter erweckt. Folgt wortgetreu allen Anweisungen.`,
                gabeZiel: "",
                qs,
                ziel: targetActor,
                disabled: true,
                showIcon: 1,
                flags: {
                    dsk: {
                        isToteErweckenZiel: true,
                        casterUuid: casterActor.uuid,
                        sourceCasterUuid: casterActor.uuid,
                        qs,
                        wirkungsende: {
                            sfName: endeKey,
                            basisEffektName: vollerName,
                            beschreibungFuerEnde: endeText
                        }
                    }
                }
            });

            if (!zielEffekt) {
                try { await casterEffekt.delete(); } catch {}
                misserfolge.push({ name: targetName });
                continue;
            }

            erfolge.push({ name: targetName, rolle: "Untoter Katzendiener" });
        }

        return { ok: erfolge.length > 0, erfolge, misserfolge };
    };

    // +++ 5 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++
    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!game.user.isGM || !casterActor || !daten) return false;

        if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
            ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum Wirkenden.");
            return false;
        }

        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
            return false;
        }

        const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);
        if (!casterToken) {
            ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`);
            return false;
        }

        const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
        const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
        const zieleListe = daten.ziele || [];

        let res = { ok: false, erfolge: [], misserfolge: foundry.utils.deepClone(daten.misserfolge || []) };
        try {
            res = await wendeEffekteAn({ casterActor, zieleListe, qs });
        } catch (error) {
            console.error("Tote erwecken: Effektanlage fehlgeschlagen.", { casterActor, daten, error });
        }

        const reichweite = qs * 10;
        const dienerZahl = zaehleKontrollierteDiener(casterActor);
        const maxDiener = qs * 2;

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId,
            gabenName: vollerName,
            ahne,
            beschreibung: daten.beschreibung || beschreibungFuer(casterName, reichweite, dienerZahl, maxDiener),
            wirkender: casterName,
            ziele: res.erfolge,
            misserfolge: [...res.misserfolge, ...(daten.misserfolge || [])],
            dauerText: "Permanent (bis zur Zerstörung)",
            erfolgreich: res.ok
        });

        if (res.ok) {
            ui.notifications.info(`Luna sagt 🌙: Tote erwecken erfolgreich auf ${res.erfolge.length} Ziel(e) angewendet.`);
        } else {
            ui.notifications.error("Luna sagt 🌙: Tote erwecken konnte auf keines der Ziele angewendet werden!");
        }

        return true;
    };

    // +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++
    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
                if (!daten) continue;

                if (await verarbeiteAnfrage(anfrageActor, daten)) {
                    await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
                }
            }

            return;
        }
    }

    // +++ 7 - WIRKENDER +++++++++++++++++++++++++++++++++++++++++++
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor).find(actor =>
                actor?.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            game.actors.find(actor =>
                actor.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            null;
    }

    if (!casterActor) {
        return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");
    }

    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!"
        );
    }

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // +++ 8 - QS ++++++++++++++++++++++++++++++++++++++++++++++++++
    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor,
        gabenName,
        suchbegriffe: ["Tote erwecken Probe", "Tote erwecken"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0,
        protokollieren: true
    });

    if (qs <= 0) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName,
            ahne,
            beschreibung: "Die dunkle Magie konnte nicht gebündelt werden.",
            wirkender: casterName,
            ziele: [],
            misserfolge: [{ name: casterName }],
            dauerText: "Keine Wirkung",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 9 - ALLE TARGETS PRÜFEN (NUR LEBENDE WESEN, DIE BESIEGT SIND) +++
    const targets = Array.from(game.user.targets || []);

    if (!targets.length) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle mindestens ein totes Ziel per Target aus!"
        );
    }

    const maxDiener = qs * 2;
    let aktuelleDiener = zaehleKontrollierteDiener(casterActor);
    const gueltigeZiele = [];
    const misserfolge = [];

    for (const tToken of targets) {
        const tActor = tToken?.actor;
        const tName = tToken?.name || tActor?.name || "Unbekanntes Ziel";

        if (!tActor || !istGueltigesLebewesen(tActor) || !istBesiegt(tActor, tToken)) {
            misserfolge.push({ name: tName });
            continue;
        }

        if (aktuelleDiener >= maxDiener) {
            misserfolge.push({ name: tName });
            continue;
        }

        aktuelleDiener++;
        gueltigeZiele.push({
            actorUuid: tActor.uuid,
            tokenId: tToken.id,
            tokenUuid: tToken.document?.uuid || tToken.uuid || null,
            name: tName
        });
    }

    const reichweite = qs * 10;
    const beschreibung = beschreibungFuer(casterName, reichweite, zaehleKontrollierteDiener(casterActor) + gueltigeZiele.length, maxDiener);

    if (!gueltigeZiele.length) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName,
            ahne,
            beschreibung,
            wirkender: casterName,
            ziele: [],
            misserfolge,
            dauerText: "Keine Wirkung",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 10 - KARTE + GM-BUTTON ++++++++++++++++++++++++++++++++++
    const gmLink = DSK_FW.GabenUI.GMMakroButton(
        macroUuid,
        "Diener erwecken",
        "Das Makro muss durch die Spielleitung ausgeführt werden."
    );

    const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung,
        wirkender: casterName,
        ziele: gueltigeZiele.map(z => ({ name: z.name, rolle: "Untoter Katzendiener" })),
        misserfolge,
        dauerText: "Permanent (bis zur Zerstörung)",
        gmLink,
        gmBereich: !game.user.isGM,
        anfragenderUserId: game.user.id
    });

    if (!nachricht) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error(
            "Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!"
        );
    }

    const anfrageDaten = {
        casterUuid: casterActor.uuid,
        casterName,
        casterTokenId: casterToken.id,
        casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
        ziele: gueltigeZiele,
        misserfolge,
        qs,
        beschreibung,
        sceneId: canvas.scene?.id || null,
        requestedByUserId: game.user.id,
        messageId: nachricht.id,
        macroUuid,
        erstellt: Date.now()
    };

    // +++ 11 - DIREKT ODER GM-ANFRAGE +++++++++++++++++++++++++++++
    if (game.user.isGM) {
        await verarbeiteAnfrage(casterActor, anfrageDaten);
        await raeumeQSAuf(casterActor);
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
    await raeumeQSAuf(casterActor);

    ui.notifications.info(
        "Luna sagt 🌙: Tote erwecken wurde bei der Spielleitung zur Anwendung beantragt."
    );
}).call(this);
